mapper.select:
SELECT n.notice_id, n.notice_title, n.notice_type, n.notice_content, n.STATUS, n.create_by, n.create_time, n.update_by, n.update_time, r.is_read isRead FROM sys_notice_read r LEFT JOIN sys_notice n ON n.notice_id = r.notice_id AND r.user_id = #{userId} WHERE n.status = 1
and n.notice_type=#{noticeType}
ORDER BY isRead ASC,n.create_time DESC

SELECT COUNT(*) AS unread_count
FROM sys_notice_read
WHERE user_id = #{userId}
  AND is_read = 0;
